  writeFileSync(
    join(project, "decisions", "notes.json"),
    JSON.stringify(complete({
      schema: LATEST, id: "notes-x", alias: "E90", statement: "Notes",
    }), null, 2) + "\n",
    "utf8",
  );

  const rendered = spawnSync(process.execPath,
    [tool("render")], { cwd: project, encoding: "utf8" });
